// FUNCTION: BFME2 0x001172B0 size=317 name=?Prepare_Render_New_Frame@WW3D@@SA_NXZ evidence=N:ledger tier=A

// FUNCTION: BFME2 0x001173F0 size=22 name=?rva001173f0@@YAXI@Z evidence=?:placeholder tier=A

// FUNCTION: BFME2 0x00117410 size=72 name=?End_Render@WW3D@@SA_N_N@Z evidence=N:ledger tier=A
bool WW3D::End_Render(bool flip_frame)
{
	if (!IsInitted) {
		return true;
	}

	// If sorting renderer flush isn't called from within any of the render functions the sorting arrays will overflow!
	SortingRendererClass::Flush();

	IsRendering = false;

	DX8Wrapper::End_Scene(flip_frame);

	FrameCount++;

	if (flip_frame) Debug_Statistics::End_Statistics();
	Debug_Statistics::Record_Draw_Call_Batch();

	Activate_Snapshot(false);

	// (gth) I've found some cases where its not safe to rely on our "shadow" copy (of matrices for example) across multiple
	// frames.  So even though this is slightly less "optimal", lets just reset the caches each frame.
	DX8Wrapper::Invalidate_Cached_Render_States();

	return true;
}


