// FUNCTION: BFME2 0x001184D0 size=95 name=?Normalize_Coordinates@WW3D@@SAXHHAAM0@Z evidence=N:ledger tier=B hypothesis:Z
void WW3D::Normalize_Coordinates(int x, int y, float &fx, float &fy)
{
	// clip the coordinates back into the resolution of the screen
	x = Bound(x, 0, DX8Wrapper::Get_Device_Resolution_Width());
	y = Bound(y, 0, DX8Wrapper::Get_Device_Resolution_Height());

	// now that the coordinates are clipped convert them to their normalized values.
	fx = (float)x / DX8Wrapper::Get_Device_Resolution_Width();
	fy = (float)y / DX8Wrapper::Get_Device_Resolution_Height();
}

// FUNCTION: BFME2 0x00118530 size=213 name=?Start_Movie_Capture@WW3D@@SAXPBDMH_N@Z evidence=N:ledger tier=B hypothesis:Z
void WW3D::Start_Movie_Capture(const char *filename_base, float frame_rate, int buffer_count, bool compress)
{
	if (IsCapturing)
		Stop_Movie_Capture();

	IsCapturing = true;
	RECT bounds;
	::GetWindowRect(static_cast<HWND>(g_WW3D_Hwnd), &bounds);
	int height = bounds.bottom - bounds.top;
	int width = bounds.right - bounds.left;

	if (frame_rate == 0.0f) {
		frame_rate = 1.0f;
		PauseRecord = true;
	} else {
		PauseRecord = false;
	}

	Movie = new FrameGrabClass(filename_base, width, height, 24, frame_rate, buffer_count, compress);
}

// FUNCTION: BFME2 0x00118610 size=48 name=?Toggle_Movie_Capture@WW3D@@SA_NPBDMH_N@Z evidence=N:ledger tier=B hypothesis:Z
bool WW3D::Toggle_Movie_Capture(const char *filename_base, float frame_rate, int buffer_count, bool compress)
{
	if (IsCapturing) {
		Stop_Movie_Capture();
		return false;
	}
	Start_Movie_Capture(filename_base, frame_rate, buffer_count, compress);
	return true;
}

